const { execFileSync } = require('child_process');
const fs = require('fs');
const EXE = '/workspace/dataset/test13_executable';
const F = '/workspace/probes/combinators.jsonl';
function run(a, b) {
  try {
    const out = execFileSync(EXE, ['--a', a, '--b', b], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
    return { out, exit: 0 };
  } catch (e) {
    return { out: e.stdout || '', exit: (e.status === null || e.status === undefined) ? -1 : e.status };
  }
}
const L = fs.readFileSync(F, 'utf8').trim().split('\n').map(JSON.parse);
let mism = 0;
L.forEach((v, i) => {
  const r = run(v.a, v.b);
  if (r.out !== v.out || r.exit !== v.exit) {
    mism++;
    console.log('MISMATCH line', i + 1, 'schema=', v.b.slice(0, 80), 'recorded=', JSON.stringify(v.out), v.exit, 'actual=', JSON.stringify(r.out), r.exit);
  }
});
console.log('verified', L.length, 'mismatches', mism);

