const { go, raw } = require('/tmp/pr/lib');
const C = [];
const vals = ['""', '{}', '0', 'null', 'true', 'false', '"x"', '"ab"', '[]',
  '{"type":"number"}', '{"a":{"type":"number"}}', '1.5', '{"":{}}'];
for (const kw of ['allOf', 'anyOf', 'oneOf']) {
  for (const v of vals) C.push([raw('"ab"'), raw('{"' + kw + '":' + v + '}')]);
}
for (const v of ['{}', 'true', 'false', '[]', '""', '"x"', '0', 'null', '1.5', '[{"type":"number"}]']) {
  C.push([raw('"ab"'), raw('{"not":' + v + '}')]);
}
for (const v of ['{}', 'true', 'false', '[]', '""', '0', 'null', '{"type":"string"}']) {
  C.push([raw('"ab"'), raw('{"if":' + v + ',"then":{"minLength":9},"else":{"maxLength":0}}')]);
}
// contains / propertyNames malformed
for (const v of ['null', '1', '[]', '""']) {
  C.push([raw('[1]'), raw('{"contains":' + v + '}')]);
  C.push([raw('{"a":1}'), raw('{"propertyNames":' + v + '}')]);
}
go(C, 'malformed');

